def parse_time(value):
    h, m = map(int, value.split(":"))
    return h * 60 + m

def format_time(value):
    return f"{value // 60:02d}:{value % 60:02d}"

WORK_START = parse_time("09:00")
WORK_END = parse_time("17:00")
DURATION = 30

DAYS = ("Monday", "Tuesday")

BUSY = {
    "Jeffrey": {
        "Monday": [],
        "Tuesday": [],
    },
    "Harold": {
        "Monday": [
            ("09:00", "10:00"),
            ("10:30", "17:00"),
        ],
        "Tuesday": [
            ("09:00", "09:30"),
            ("10:30", "11:30"),
            ("12:30", "13:30"),
            ("14:30", "15:30"),
            ("16:00", "17:00"),
        ],
    },
}

def has_conflict(person, day, start, end):
    for busy_start, busy_end in BUSY[person][day]:
        bs = parse_time(busy_start)
        be = parse_time(busy_end)
        if start < be and end > bs:
            return True
    return False

def slot_ok(day, start, end):
    if start < WORK_START or end > WORK_END:
        return False
    if any(has_conflict(person, day, start, end) for person in BUSY):
        return False
    # Harold prefers Tuesday, and would like the meeting to be before 14:30.
    if day != "Tuesday" or end > parse_time("14:30"):
        return False
    return True

solution = None
for day in DAYS:
    for start in range(WORK_START, WORK_END - DURATION + 1, DURATION):
        end = start + DURATION
        if slot_ok(day, start, end):
            solution = [day, format_time(start), format_time(end)]
            break
    if solution is not None:
        break

if solution is None:
    raise RuntimeError("No valid slot found")

print(solution)

