# Variables: day, start, end. end = start + 30.
# Domain: Monday/Tuesday/Wednesday; slots from 09:00 to 16:30.
# Constraints: within work hours, no overlap with busy intervals,
# and Pamela preference: no new Monday meeting, no new Tuesday meeting,
# no Wednesday meeting before 16:00.

DAYS = ["Monday", "Tuesday", "Wednesday"]
WORK_START = 9 * 60
WORK_END = 17 * 60
MEETING_LENGTH = 30

AMY_BUSY = {
    "Monday": [],
    "Tuesday": [],
    "Wednesday": [
        (11 * 60, 11 * 60 + 30),
        (13 * 60 + 30, 14 * 60),
    ],
}

PAMELA_BUSY = {
    "Monday": [
        (9 * 60, 10 * 60 + 30),
        (11 * 60, 16 * 60 + 30),
    ],
    "Tuesday": [
        (9 * 60, 9 * 60 + 30),
        (10 * 60, 17 * 60),
    ],
    "Wednesday": [
        (9 * 60, 9 * 60 + 30),
        (10 * 60, 11 * 60),
        (11 * 60 + 30, 13 * 60 + 30),
        (14 * 60 + 30, 15 * 60),
        (16 * 60, 16 * 60 + 30),
    ],
}

BUSY = {
    "Amy": AMY_BUSY,
    "Pamela": PAMELA_BUSY,
}

def fmt(minutes):
    return f"{minutes // 60:02d}:{minutes % 60:02d}"

def is_free(start, end, intervals):
    return all(
        end <= busy_start or start >= busy_end
        for busy_start, busy_end in intervals
    )

def preference_ok(day, start):
    return day == "Wednesday" and start >= 16 * 60

def valid(day, start, end):
    if not (WORK_START <= start and end <= WORK_END):
        return False
    if not preference_ok(day, start):
        return False
    return all(
        is_free(start, end, BUSY[person][day])
        for person in BUSY
    )

def main():
    for day in DAYS:
        for start in range(WORK_START, WORK_END, MEETING_LENGTH):
            end = start + MEETING_LENGTH
            if valid(day, start, end):
                print([day, fmt(start), fmt(end)])
                return

if __name__ == "__main__":
    main()

