# Variables: meeting day, start time, and end time.
# Domains: start/end in HH:MM within 09:00-17:00, meeting length 30 minutes.
# Constraints: no busy-interval overlap for any participant, and Roger's
# preferred start is at or after 12:30.

def to_minutes(t):
    h, m = map(int, t.split(":"))
    return h * 60 + m

def to_hhmm(m):
    return f"{m // 60:02d}:{m % 60:02d}"

DAY = "Monday"
WORK_START = to_minutes("09:00")
WORK_END = to_minutes("17:00")
DURATION = 30

participants = [
    "Daniel", "Kathleen", "Carolyn", "Roger",
    "Cheryl", "Virginia", "Angela"
]

busy_intervals = {
    "Daniel": [],
    "Kathleen": [("14:30", "15:30")],
    "Carolyn": [("12:00", "12:30"), ("13:00", "13:30")],
    "Roger": [],
    "Cheryl": [
        ("09:00", "09:30"),
        ("10:00", "11:30"),
        ("12:30", "13:30"),
        ("14:00", "17:00"),
    ],
    "Virginia": [
        ("09:30", "11:30"),
        ("12:00", "12:30"),
        ("13:00", "13:30"),
        ("14:30", "15:30"),
        ("16:00", "17:00"),
    ],
    "Angela": [
        ("09:30", "10:00"),
        ("10:30", "11:30"),
        ("12:00", "12:30"),
        ("13:00", "13:30"),
        ("14:00", "16:30"),
    ],
}

# Roger prefers not to meet before 12:30, so his start time must be >= 12:30.
preferences = {
    "Roger": {"not_before": to_minutes("12:30")},
}

def overlaps(person, start, end):
    for interval_start, interval_end in busy_intervals[person]:
        s = to_minutes(interval_start)
        e = to_minutes(interval_end)
        if start < e and s < end:
            return True
    return False

def satisfies_preferences(person, start):
    if person in preferences:
        if start < preferences[person]["not_before"]:
            return False
    return True

def feasible(start):
    end = start + DURATION
    if end > WORK_END:
        return False
    for person in participants:
        if overlaps(person, start, end):
            return False
        if not satisfies_preferences(person, start):
            return False
    return True

for start in range(WORK_START, WORK_END - DURATION + 1):
    if feasible(start):
        print([DAY, to_hhmm(start), to_hhmm(start + DURATION)])
        break

