def to_minutes(time_string):
    hours, minutes = map(int, time_string.split(":"))
    return hours * 60 + minutes

def to_hhmm(minutes):
    return f"{minutes // 60:02d}:{minutes % 60:02d}"

def intervals_overlap(start_a, end_a, start_b, end_b):
    return start_a < end_b and start_b < end_a

def main():
    days = ["Monday", "Tuesday", "Wednesday"]
    workday_start = to_minutes("09:00")
    workday_end = to_minutes("17:00")
    meeting_duration = 30

    existing_meetings = {
        "Larry": {
            "Monday": [],
            "Tuesday": [],
            "Wednesday": [],
        },
        "Samuel": {
            "Monday": [
                ("10:30", "11:00"),
                ("12:00", "12:30"),
                ("13:00", "15:00"),
                ("15:30", "16:30"),
            ],
            "Tuesday": [
                ("09:00", "12:00"),
                ("14:00", "15:30"),
                ("16:30", "17:00"),
            ],
            "Wednesday": [
                ("10:30", "11:00"),
                ("11:30", "12:00"),
                ("12:30", "13:00"),
                ("14:00", "14:30"),
                ("15:00", "16:00"),
            ],
        },
    }

    existing_meetings_minutes = {}
    for participant in existing_meetings:
        existing_meetings_minutes[participant] = {}
        for day in days:
            existing_meetings_minutes[participant][day] = [
                (to_minutes(start), to_minutes(end))
                for start, end in existing_meetings[participant][day]
            ]

    for day in days:
        start = workday_start
        while start + meeting_duration <= workday_end:
            end = start + meeting_duration
            available = True
            for participant in existing_meetings_minutes:
                for busy_start, busy_end in existing_meetings_minutes[participant][day]:
                    if intervals_overlap(start, end, busy_start, busy_end):
                        available = False
                        break
                if not available:
                    break
            if available:
                print([day, to_hhmm(start), to_hhmm(end)])
                return
            start += meeting_duration

if __name__ == "__main__":
    main()
